/**
 * manage_effect records: particle/Niagara core, debug and lifecycle, Niagara
 * parameters, emitter props, modules, renderers, data interfaces, events, GPU
 * sim and validation. Niagara-gated via the Niagara plugin.
 */
import type { CapabilityRecordSource, JsonObject } from '../../../model.js';
import { buildRecord } from '../helpers.js';
import { ANY_EDITOR_STATE } from '../../core/builder.js';
import { P } from '../properties.js';
import { E } from './effect-properties.js';
import { bool, str } from '../../shared/schema-props.js';
import { LIGHT_COLOR_TEXT } from '../../shared/light-text.js';

const T = 'manage_effect';
// Every Niagara asset edit here saves unless told not to.
const SAVE = bool('Persist the asset to disk (default true); false leaves the change in memory only.');
const F = 'effect';
const W = ['A particle, Niagara or debug effect must be authored or run.'];
const NIAGARA = ['Niagara'];
// emitterName is never required: LoadSystemAndEmitter reads it or emitter, and a system with one emitter needs neither.
const EMITTER_REQUIRED = ['systemPath'];
// Every Niagara system edit and module resolves the system from systemPath, else assetPath (FActionContext::SystemPath; the graph
// route reads assetPath, then systemPath). A variant that declared one spelling only made the other look like a parameter of its
// siblings, so a call was told it ignored a path it had read: each declares both, and one is required.
const EMITTER_ONLY: string[] = [];
const SYSTEM_ONE_OF = ['systemPath', 'assetPath'];
// Tuning one emitter took a call per value; set_parameter_value writes a list and saves the system once.
const PARAMETER_LIST: JsonObject = {
  type: 'array', minItems: 1, maxItems: 200,
  items: { type: 'object', properties: { parameterName: E.parameterName, parameterValue: E.parameterValue }, required: ['parameterName', 'parameterValue'], additionalProperties: false },
  description: 'Several values written together and saved once, in place of parameterName and parameterValue: each {parameterName, parameterValue} names a user parameter, a module input or a module\'s static switch as get_niagara_info lists it (InitializeParticle.Lifetime, InitializeParticle.Ribbon Width Mode), and emitterName and save apply to every entry. With actorName (edit=set_parameter) each entry is a user parameter of that placed effect, in place of parameterName and value. The reply lists every entry (parameterName, applied, error); the call fails PARAMETER_BATCH_INCOMPLETE naming any that did not apply, and the others stay written.',
};

